INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002f9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss urbanism and urban planning at B2","Use Urbanismus und Stadtplanung vocabulary","Talk about Germany''s urban development, gentrification, and Smart City concepts"],"explanation":{"intro":"Urbanism and urban planning vocabulary covers gentrification, Smart City, and Germany''s urban development challenges at B2.","culturalNote":"Urbanismus und Stadtplanung: Germany: Reurbanisierung (reurbanisation — after 1990s suburbanisation, cities grew again after 2000). Stadtumbau Ost (urban restructuring East Germany — shrinking cities — vacant buildings — Leerstand). Key: Gentrifikation (gentrification — Berlin, Hamburg, Munich — Mietpreisbremse vs. market forces). Smart City (Berlin, Hamburg initiatives). IBA (Internationale Bauausstellung — major architecture/planning events). Leipzig: Gründerzeitquartiere (Wilhelminian era — renovation success story). Baugruppen (community self-build groups — Berlin alternative). Key: Bauleitplanung (land-use planning — Bebauungsplan, Flächennutzungsplan). Stadtentwicklung (urban development). Dichte (density). Nutzungsmischung (mixed use — urban quality). Key debate: Wachstumsstadt vs. schrumpfende Stadt (growing vs. shrinking city — East German reality). Suburbanisierung. Car-free zones. 15-minute city (15-Minuten-Stadt)."},"examples":[{"german":"Gentrifikation bezeichnet einen paradoxen urbanen Prozess: Die Aufwertung eines Stadtviertels durch Sanierung, Kultureinrichtungen und neue Mittelschichtsbewohner verbessert die bauliche Qualität, verdrängt aber die ursprüngliche Bevölkerung durch steigende Mieten — ein Prozess, der individuelle Mobilitätsentscheidungen mit strukturellen Wohnungsmarktdynamiken verknüpft und politische Steuerung herausfordert.","english":"Gentrification designates a paradoxical urban process: the upgrading of a city district through renovation, cultural facilities, and new middle-class residents improves building quality, but displaces the original population through rising rents — a process that links individual mobility decisions with structural housing market dynamics and challenges political steering."},{"german":"Das Konzept der 15-Minuten-Stadt reagiert auf das Mobilitätsproblem der modernen Großstadt: Wenn alle wesentlichen Alltagsfunktionen — Arbeit, Einkauf, Bildung, Erholung — innerhalb von 15 Gehminuten erreichbar sind, sinken Pendelzeiten, CO2-Emissionen und Verkehrsbelastungen, während Lebensqualität und soziale Kohäsion steigen. Die Umsetzung erfordert eine grundlegende Nutzungsmischung, die dem Trennungsprinzip der Nachkriegsstadtplanung widerspricht.","english":"The concept of the 15-minute city responds to the mobility problem of the modern metropolis: when all essential everyday functions — work, shopping, education, recreation — are reachable within 15 minutes on foot, commuting times, CO2 emissions, and traffic loads fall, while quality of life and social cohesion rise. Implementation requires a fundamental mixed use that contradicts the separation principle of postwar urban planning."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss gentrification, the 15-minute city, and Germany''s urban development at B2."}}',
'{"items":[{"word":"die Aufwertung","translation":"upgrading","pronunciation":"dee OWF-ver-toong","example":"Stadtteile aufwerten."},{"word":"verdrängen","translation":"to displace","pronunciation":"fer-DRENG-en","example":"Bewohner verdrängen."},{"word":"die Kohäsion","translation":"cohesion","pronunciation":"dee ko-HÄ-zyon","example":"Soziale Kohäsion."},{"word":"das Pendelzeit","translation":"commuting time","pronunciation":"dahs PEN-del-tsyt","example":"Pendelzeiten reduzieren."},{"word":"die Nutzungsmischung","translation":"mixed use","pronunciation":"dee NOOT-soongs-mi-shoong","example":"Stadtplanerische Nutzungsmischung."},{"word":"widersprechen","translation":"to contradict","pronunciation":"vi-der-SHPREKH-en","example":"Dem Prinzip widersprechen."}]}',
'{"title":"Etwas verknüpft X mit Y — something links X with Y","pattern":"etwas verknüpft X mit Y = something links X with Y (verknüpfen mit + dative/accusative — marks a connection between two things that were previously seen as separate; verknüpft = linked, connected — past participle of verknüpfen)","explanation":"Verknüpfen mit = to link with, connect with (knüpfen = to knot, tie; ver- intensifies; verknüpfen = to interlink, connect). Ein Prozess, der X mit Y verknüpft = a process that links X with Y. The phrase marks that two things are brought into connection, showing how they affect each other. Wider than verbinden (to connect — more general), it implies a structural linking: Gentrifikation verknüpft individuelle Entscheidungen mit strukturellen Dynamiken. Compare: verbinden (to connect — more physical/direct), zusammenführen (to bring together), in Beziehung setzen (to put in relation to — more analytical), vernetzen (to network — more systemic).","examples":[{"sentence":"Der Bericht verknüpft Bildungserfolg mit sozioökonomischen Hintergründen.","translation":"The report links educational success with socioeconomic backgrounds."},{"sentence":"Das Gesetz verknüpft Steuervorteile mit Nachhaltigkeitskriterien.","translation":"The law links tax advantages with sustainability criteria."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verdrängen'' means?","options":["to displace","to push out","to remove","to oust"],"correctAnswer":"to displace"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The concept of the 15-minute city responds to the mobility problem of the modern metropolis: when all essential everyday functions — work, shopping, education, recreation — are reachable within 15 minutes on foot, commuting times, CO2 emissions, and traffic loads fall, while quality of life and social cohesion rise. Implementation requires a fundamental mixed use that contradicts the separation principle of postwar urban planning.","options":["Das Konzept der 15-Minuten-Stadt reagiert auf das Mobilitätsproblem der modernen Großstadt: Wenn alle wesentlichen Alltagsfunktionen — Arbeit, Einkauf, Bildung, Erholung — innerhalb von 15 Gehminuten erreichbar sind, sinken Pendelzeiten, CO2-Emissionen und Verkehrsbelastungen, während Lebensqualität und soziale Kohäsion steigen. Die Umsetzung erfordert eine grundlegende Nutzungsmischung, die dem Trennungsprinzip der Nachkriegsstadtplanung widerspricht.","Die 15-Minuten-Stadt reduziert Pendeln durch gemischte Nutzung in Fußnähe.","Wenn alle Alltagsfunktionen nah sind, braucht man kein Auto und lebt besser.","Nachkriegsstadtplanung hat Funktionen getrennt — die 15-Minuten-Stadt kehrt das um."],"correctAnswer":"Das Konzept der 15-Minuten-Stadt reagiert auf das Mobilitätsproblem der modernen Großstadt: Wenn alle wesentlichen Alltagsfunktionen — Arbeit, Einkauf, Bildung, Erholung — innerhalb von 15 Gehminuten erreichbar sind, sinken Pendelzeiten, CO2-Emissionen und Verkehrsbelastungen, während Lebensqualität und soziale Kohäsion steigen. Die Umsetzung erfordert eine grundlegende Nutzungsmischung, die dem Trennungsprinzip der Nachkriegsstadtplanung widerspricht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Bericht verknüpft Bildungserfolg mit sozioökonomischen ___.","options":["Hintergründen","Faktoren","Merkmalen","Einflüssen"],"correctAnswer":"Hintergründen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The law links tax advantages with sustainability criteria","wordBankItems":["Das","Gesetz","verknüpft","Steuervorteile","mit","Nachhaltigkeitskriterien","."],"correctAnswer":"Das Gesetz verknüpft Steuervorteile mit Nachhaltigkeitskriterien ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Nutzungsmischung'' means?","options":["mixed use","land use mix","functional mix","mixed zoning"],"correctAnswer":"mixed use"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002fa',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss housing policy at B2","Use Wohnungspolitik vocabulary","Talk about Germany''s housing shortage, rent control, and Mietpreisbremse"],"explanation":{"intro":"Housing policy vocabulary covers Germany''s housing shortage, rent control laws, and tenant rights at B2.","culturalNote":"Wohnungspolitik: Germany: traditionally high tenancy rate (50% renters — one of highest in Europe — historical post-war rebuilding by public landlords). Key: Wohnungsnot (housing emergency — especially Berlin, Munich, Hamburg). Mietpreisbremse (rent brake — introduced 2015 — limits rent increases to 10% above local rent index). Milieuschutz (social milieu protection — designates areas where displacement of lower-income tenants is regulated). Sozialwohnungen (social housing — massively reduced from 2.5M in 1990 to 1.1M 2019 — privatisation). Deutsche Wohnen & Co enteignen (Berlin referendum 2021 — 56% voted for expropriation of large landlords — not yet implemented). Grundsteuer (property tax — reform 2025). Key: Eigentumsquote vs. Mieterquote. Vonovia (Germany''s largest landlord — 600,000 apartments — shareholder controversy). Mieterverbände vs. Eigentümerverbände. Baulandmobilisierung (land for housing)."},"examples":[{"german":"Der deutsche Wohnungsmarkt befindet sich in einer strukturellen Angebotslücke: Jahrzehntelanger Rückgang des sozialen Wohnungsbaus, steigende Baukosten und wachsende urbane Nachfrage haben ein Defizit erzeugt, das Mietpreisbremsen allein nicht schließen können — weil diese die Nachfrage nicht verringern, nur die Mietdynamik für Bestandsmieter stabilisieren, während Neuvermietungen und Neubauten ausgenommen bleiben.","english":"The German housing market finds itself in a structural supply gap: decades-long decline of social housing construction, rising building costs, and growing urban demand have created a deficit that rent brakes alone cannot close — because these do not reduce demand, only stabilise the rent dynamics for existing tenants, while new lettings and new construction remain exempt."},{"german":"Das Berliner Volksbegehren zur Enteignung von Wohnungsunternehmen hat eine grundlegende Frage nach den Grenzen der Sozialpflichtigkeit des Eigentums aufgeworfen: Artikel 14 Abs. 2 GG bestimmt, dass Eigentum verpflichtet und sein Gebrauch dem Wohle der Allgemeinheit dienen soll — eine Norm, die in der Wohnungsfrage als Grundlage für weitreichende Regulierung oder sogar Vergesellschaftung herangezogen wird.","english":"The Berlin referendum on expropriation of housing companies has raised a fundamental question about the limits of the social obligation of property: Article 14 para. 2 of the Basic Law specifies that property obliges and its use should serve the common good — a norm that in the housing question is invoked as the basis for far-reaching regulation or even socialisation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s housing shortage, Mietpreisbremse, and the expropriation debate at B2."}}',
'{"items":[{"word":"die Angebotslücke","translation":"supply gap","pronunciation":"dee AN-geh-bohts-lü-keh","example":"Strukturelle Angebotslücke."},{"word":"das Bestandsmieter","translation":"existing tenant","pronunciation":"dahs beh-SHTANTS-mee-ter","example":"Bestandsmieter schützen."},{"word":"die Sozialpflichtigkeit","translation":"social obligation","pronunciation":"dee zo-TSYAHL-pflikh-tikh-kyt","example":"Sozialpflichtigkeit des Eigentums."},{"word":"heranziehen","translation":"to invoke/draw upon","pronunciation":"her-AN-tsee-en","example":"Als Grundlage heranziehen."},{"word":"die Vergesellschaftung","translation":"socialisation","pronunciation":"dee fer-geh-ZEL-shaf-toong","example":"Vergesellschaftung von Wohnraum."},{"word":"das Volksbegehren","translation":"referendum/citizen initiative","pronunciation":"dahs FOLKS-beh-geh-ren","example":"Volksbegehren starten."}]}',
'{"title":"Etwas als Grundlage für X heranziehen — to invoke something as the basis for X","pattern":"etwas als Grundlage für X heranziehen = to invoke/draw on something as the basis for X (heranziehen = to draw upon, invoke — separable: zieht...heran; als Grundlage für + accusative = as the basis for X)","explanation":"Heranziehen = to draw on, invoke, consult (separable: zieht...heran — brings forward as a reference or basis). Als Grundlage für X heranziehen = to draw on as the basis for X. Heranziehen is used when citing a principle, norm, or precedent as a foundation or justification for a conclusion or action. Art. 14 Abs. 2 GG wird als Grundlage für Enteignung herangezogen = Art. 14 para. 2 GG is invoked as the basis for expropriation. Compare: berufen auf (to appeal to — more rights-claiming), zitieren (to cite — more quotation-based), verweisen auf (to refer to — pointing only, not using as basis), stützen auf (to base on — more structural foundation).","examples":[{"sentence":"Die Richter zogen internationale Menschenrechtsnormen als Grundlage heran.","translation":"The judges invoked international human rights norms as the basis."},{"sentence":"Der Kläger zog den Vertrag als Grundlage für seine Forderung heran.","translation":"The plaintiff invoked the contract as the basis for his claim."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Angebotslücke'' means?","options":["supply gap","supply deficit","housing shortage","capacity gap"],"correctAnswer":"supply gap"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The German housing market finds itself in a structural supply gap: decades-long decline of social housing construction, rising building costs, and growing urban demand have created a deficit that rent brakes alone cannot close — because these do not reduce demand, only stabilise the rent dynamics for existing tenants, while new lettings and new construction remain exempt.","options":["Der deutsche Wohnungsmarkt befindet sich in einer strukturellen Angebotslücke: Jahrzehntelanger Rückgang des sozialen Wohnungsbaus, steigende Baukosten und wachsende urbane Nachfrage haben ein Defizit erzeugt, das Mietpreisbremsen allein nicht schließen können — weil diese die Nachfrage nicht verringern, nur die Mietdynamik für Bestandsmieter stabilisieren, während Neuvermietungen und Neubauten ausgenommen bleiben.","Die Mietpreisbremse hilft bestehenden Mietern, löst aber den Wohnungsmangel nicht.","Sozialer Wohnungsbau ist eingebrochen — mehr Angebot ist die einzige Lösung.","Mietpreisbremsen sind Symptombekämpfung; das Grundproblem ist fehlender Wohnraum."],"correctAnswer":"Der deutsche Wohnungsmarkt befindet sich in einer strukturellen Angebotslücke: Jahrzehntelanger Rückgang des sozialen Wohnungsbaus, steigende Baukosten und wachsende urbane Nachfrage haben ein Defizit erzeugt, das Mietpreisbremsen allein nicht schließen können — weil diese die Nachfrage nicht verringern, nur die Mietdynamik für Bestandsmieter stabilisieren, während Neuvermietungen und Neubauten ausgenommen bleiben."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Richter zogen internationale Menschenrechtsnormen als Grundlage ___.","options":["heran","hin","ein","vor"],"correctAnswer":"heran"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The plaintiff invoked the contract as the basis for his claim","wordBankItems":["Der","Kläger","zog","den","Vertrag","als","Grundlage","für","seine","Forderung","heran","."],"correctAnswer":"Der Kläger zog den Vertrag als Grundlage für seine Forderung heran ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Volksbegehren'' means?","options":["referendum/citizen initiative","public petition","popular vote","citizens'' initiative"],"correctAnswer":"referendum/citizen initiative"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002fb',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss traffic and mobility at B2","Use Verkehr und Mobilität vocabulary","Talk about Germany''s car culture, Verkehrswende, and public transport policy"],"explanation":{"intro":"Traffic and mobility vocabulary covers Germany''s car culture, Verkehrswende (transport transition), and the debate over public transport at B2.","culturalNote":"Verkehr und Mobilität: Germany: Automobilnation (car-loving nation — VW, BMW, Daimler). Stau (traffic jam — Deutschland: 5. place globally). Verkehrswende (transport transition — away from car toward public transport, cycling, walking). ÖPNV (public transport — Öffentlicher Personennahverkehr). Deutschlandticket (49€/month — January 2023 — national public transport ticket — massive success: 11 million users). Bahn (Deutsche Bahn — delayed — 65% punctuality 2022). Radverkehr (cycling — Fahrradstraßen — cycling infrastructure debate). Tempolimit (speed limit — Germany: no general Autobahn speed limit — unique in Europe — debate). Verkehrsinfrastruktur (transport infrastructure — backlog). Logistik (logistics — Germany #1 globally). Last-Mile delivery. Pendler (commuters). Electric vehicles (Elektromobilität — charging infrastructure). Modal split. Flugscham (flight shame — reducing flights for climate)."},"examples":[{"german":"Die Verkehrswende ist eine der zentralen Herausforderungen der deutschen Klimapolitik: Der Straßenverkehr macht ca. 20% der deutschen CO2-Emissionen aus, und während andere Sektoren bereits deutliche Reduktionen erzielt haben, stagnieren die Emissionen im Verkehrssektor — wegen struktureller Automobilabhängigkeit, unzureichender ÖPNV-Kapazitäten und einer Subventionsstruktur, die den Pkw-Verkehr gegenüber dem öffentlichen Nahverkehr begünstigt.","english":"The transport transition is one of the central challenges of German climate policy: road transport accounts for approximately 20% of German CO2 emissions, and while other sectors have already achieved significant reductions, emissions in the transport sector are stagnating — due to structural automobile dependency, insufficient public transport capacities, and a subsidy structure that favours private car transport over public transport."},{"german":"Das Deutschlandticket zeigt, dass Preiselastizität im ÖPNV erheblich ist: Die Einführung des bundesweiten 49-Euro-Tickets hat die Nutzung des öffentlichen Nahverkehrs signifikant gesteigert und zeigt, dass Preishürden ein wesentliches Mobilitätshindernis darstellen — auch wenn Verlagerungseffekte vom Auto zum ÖPNV bescheidener ausgefallen sind als erhofft, weil Kapazitäts- und Qualitätsprobleme bestehen.","english":"The Deutschlandticket shows that price elasticity in public transport is considerable: the introduction of the nationwide 49-euro ticket has significantly increased public transport usage and shows that price barriers represent a significant mobility obstacle — even though the transfer effects from car to public transport have been more modest than hoped, because capacity and quality problems exist."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Verkehrswende, Deutschlandticket, and car culture at B2."}}',
'{"items":[{"word":"stagnieren","translation":"to stagnate","pronunciation":"shta-GNEE-ren","example":"Emissionen stagnieren."},{"word":"die Automobilabhängigkeit","translation":"automobile dependency","pronunciation":"dee ow-to-mo-BEEL-ab-heng-ikh-kyt","example":"Strukturelle Abhängigkeit."},{"word":"die Preiselastizität","translation":"price elasticity","pronunciation":"dee PRYS-eh-las-ti-tsi-TÄT","example":"Preiselastizität im Verkehr."},{"word":"bescheiden","translation":"modest","pronunciation":"beh-SHY-den","example":"Bescheidene Effekte."},{"word":"die Verlagerung","translation":"transfer/shift","pronunciation":"dee fer-LAH-geh-roong","example":"Verlagerungseffekte."},{"word":"die Preizhürde","translation":"price barrier","pronunciation":"dee PRYS-hür-deh","example":"Preishürden abbauen."}]}',
'{"title":"X macht Y% aus — X accounts for Y%","pattern":"X macht Y% aus = X accounts for Y% (ausmachen = to make up, account for — separable: macht...aus; often used with percentages, fractions, or absolute amounts to state what proportion something constitutes)","explanation":"Ausmachen = to make up, account for (separable: macht...aus). X macht Y% aus = X accounts for Y%, makes up Y%. Der Straßenverkehr macht ca. 20% der CO2-Emissionen aus = road transport accounts for approximately 20% of CO2 emissions. The phrase simply states the proportion or share that something constitutes within a larger total. Compare: beträgt Y% (amounts to Y% — more static, about total amount), repräsentiert Y% (represents Y% — more formal representation), entfällt auf X (accrues to X — used in distributional contexts).","examples":[{"sentence":"Verkehr macht 23% der weltweiten Treibhausgasemissionen aus.","translation":"Transport accounts for 23% of global greenhouse gas emissions."},{"sentence":"Erneuerbare Energien machen jetzt über 50% der deutschen Stromproduktion aus.","translation":"Renewable energies now account for over 50% of German electricity production."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Stagnieren'' means?","options":["to stagnate","to plateau","to remain static","to flatline"],"correctAnswer":"to stagnate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The transport transition is one of the central challenges of German climate policy: road transport accounts for approximately 20% of German CO2 emissions, and while other sectors have already achieved significant reductions, emissions in the transport sector are stagnating — due to structural automobile dependency, insufficient public transport capacities, and a subsidy structure that favours private car transport over public transport.","options":["Die Verkehrswende ist eine der zentralen Herausforderungen der deutschen Klimapolitik: Der Straßenverkehr macht ca. 20% der deutschen CO2-Emissionen aus, und während andere Sektoren bereits deutliche Reduktionen erzielt haben, stagnieren die Emissionen im Verkehrssektor — wegen struktureller Automobilabhängigkeit, unzureichender ÖPNV-Kapazitäten und einer Subventionsstruktur, die den Pkw-Verkehr gegenüber dem öffentlichen Nahverkehr begünstigt.","Während andere Sektoren CO2 reduzieren, stagniert der Verkehrssektor.","Der Verkehr scheitert an der Klimawende, weil Autos nach wie vor subventioniert werden.","Strukturelle Automobilabhängigkeit blockiert die Verkehrswende in Deutschland."],"correctAnswer":"Die Verkehrswende ist eine der zentralen Herausforderungen der deutschen Klimapolitik: Der Straßenverkehr macht ca. 20% der deutschen CO2-Emissionen aus, und während andere Sektoren bereits deutliche Reduktionen erzielt haben, stagnieren die Emissionen im Verkehrssektor — wegen struktureller Automobilabhängigkeit, unzureichender ÖPNV-Kapazitäten und einer Subventionsstruktur, die den Pkw-Verkehr gegenüber dem öffentlichen Nahverkehr begünstigt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Erneuerbare Energien machen jetzt über 50% der deutschen Stromproduktion ___.","options":["aus","an","ab","auf"],"correctAnswer":"aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Transport accounts for 23% of global greenhouse gas emissions","wordBankItems":["Verkehr","macht","23%","der","weltweiten","Treibhausgasemissionen","aus","."],"correctAnswer":"Verkehr macht 23% der weltweiten Treibhausgasemissionen aus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bescheiden'' means?","options":["modest","small","limited","minimal"],"correctAnswer":"modest"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002fc',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss energy transition and infrastructure at B2","Use Energiewende und Infrastruktur vocabulary","Talk about Germany''s Energiewende, grid expansion, and renewable energy challenges"],"explanation":{"intro":"Energy transition and infrastructure vocabulary covers Germany''s Energiewende, grid expansion challenges, and renewable energy at B2.","culturalNote":"Energiewende und Infrastruktur: Germany: Energiewende (energy transition — coined 1980, government policy since 2000). Erneuerbare Energiengesetz (EEG — 2000 — renewable energy subsidies). Key: 2023: over 50% electricity from renewables (wind 34%, solar 12%, biomass 7%). Atomausstieg (nuclear phase-out — last reactors closed April 2023 — post-Fukushima — 2011 decision). Key challenge: Netzausbau (grid expansion — North-South corridor — wind in North, consumption in South — grid bottlenecks). Speicher (storage — pumped hydro, batteries). Wasserstoff (hydrogen — green hydrogen ambition — H2 economy). Key debate: Kosten der Energiewende (costs — EEG surcharge — reduced 2023). Dunkelflaute (dark doldrums — winter, no wind, no sun — storage needed). Windkraftausbau (onshore wind — acceptance problems). Strompreise (electricity prices — Germany among highest in Europe). Sektorenkopplung (sector coupling — heating, transport, industry using electricity)."},"examples":[{"german":"Die Energiewende steht vor einem systemtechnischen Grundproblem: Erneuerbarer Strom ist inhärent volatil — Wind weht nicht immer, Sonne scheint nicht immer — und das Netz muss in Echtzeit Angebot und Nachfrage ausgleichen. Auf dem Weg zu einem System mit 80% erneuerbarer Stromerzeugung sind massiver Netzausbau, Lastflexibilisierung und skalierbare Speichertechnologien keine optionalen Extras, sondern systemische Voraussetzungen.","english":"The energy transition faces a fundamental systems-technical problem: renewable electricity is inherently volatile — wind does not always blow, the sun does not always shine — and the grid must balance supply and demand in real time. On the path to a system with 80% renewable electricity generation, massive grid expansion, load flexibility, and scalable storage technologies are not optional extras, but systemic prerequisites."},{"german":"Die Wasserstoffwirtschaft ist eine strategische Wette auf eine Schlüsseltechnologie: Grüner Wasserstoff — durch Elektrolyse mit erneuerbarem Strom erzeugt — könnte schwer elektrifizierbare Sektoren wie Stahl, Chemie und Langstreckenverkehr dekarbonisieren. Aber die Wirtschaftlichkeit hängt von Skalierung, Importinfrastruktur und einem Preis ab, der grünen Wasserstoff gegenüber fossilem Gas wettbewerbsfähig macht — Variablen, die politische Steuerung erfordern.","english":"The hydrogen economy is a strategic bet on a key technology: green hydrogen — produced by electrolysis with renewable electricity — could decarbonise sectors difficult to electrify, such as steel, chemicals, and long-distance transport. But economic viability depends on scaling, import infrastructure, and a price that makes green hydrogen competitive against fossil gas — variables that require political steering."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Energiewende, grid expansion challenges, and hydrogen economy at B2."}}',
'{"items":[{"word":"volatil","translation":"volatile","pronunciation":"vo-la-TEEL","example":"Volatile Energie."},{"word":"das Netzausbau","translation":"grid expansion","pronunciation":"dahs NETS-ows-bow","example":"Netzausbau vorantreiben."},{"word":"die Speichertechnologie","translation":"storage technology","pronunciation":"dee SHPY-kher-tekh-no-lo-GEE","example":"Skalierbare Speichertechnologien."},{"word":"die Elektrolyse","translation":"electrolysis","pronunciation":"dee eh-lek-tro-LÜ-zeh","example":"Elektrolyse für Wasserstoff."},{"word":"dekarbonisieren","translation":"to decarbonise","pronunciation":"deh-kar-bo-ni-ZEE-ren","example":"Schwer dekarbonisierbare Sektoren."},{"word":"wettbewerbsfähig","translation":"competitive","pronunciation":"VET-beh-verps-fä-ikh","example":"Wettbewerbsfähiger Preis."}]}',
'{"title":"Eine strategische Wette auf X — a strategic bet on X","pattern":"eine strategische Wette auf X = a strategic bet on X (Wette = bet; strategisch = strategic; auf + accusative = on X — marks a policy/investment decision made under uncertainty, where the outcome depends on X proving viable)","explanation":"Eine Wette auf X = a bet on X (Wette = bet, wager — marks that the outcome is uncertain and success depends on X working out). Strategisch = strategic (calculated, intentional — not a gamble but a reasoned assessment under uncertainty). Eine strategische Wette auf eine Schlüsseltechnologie = a strategic bet on a key technology. The phrase frames policy decisions as calculated risks — acknowledging uncertainty while explaining why the bet is rational. Compare: eine Investition in X (an investment in X — more neutral, no uncertainty emphasis), auf X setzen (to bet on X — more colloquial, same meaning), eine Wette eingehen (to place a bet — more transactional), auf X vertrauen (to trust in X — more confident).","examples":[{"sentence":"Quantencomputing ist eine strategische Wette auf eine Technologie, die in 10 Jahren transformativ sein könnte.","translation":"Quantum computing is a strategic bet on a technology that could be transformative in 10 years."},{"sentence":"Die Förderung des Mittelstands war eine strategische Wette auf dezentrale Innovation.","translation":"The promotion of SMEs was a strategic bet on decentralised innovation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Volatil'' means?","options":["volatile","variable","unstable","fluctuating"],"correctAnswer":"volatile"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The energy transition faces a fundamental systems-technical problem: renewable electricity is inherently volatile — wind does not always blow, the sun does not always shine — and the grid must balance supply and demand in real time. On the path to a system with 80% renewable electricity generation, massive grid expansion, load flexibility, and scalable storage technologies are not optional extras, but systemic prerequisites.","options":["Die Energiewende steht vor einem systemtechnischen Grundproblem: Erneuerbarer Strom ist inhärent volatil — Wind weht nicht immer, Sonne scheint nicht immer — und das Netz muss in Echtzeit Angebot und Nachfrage ausgleichen. Auf dem Weg zu einem System mit 80% erneuerbarer Stromerzeugung sind massiver Netzausbau, Lastflexibilisierung und skalierbare Speichertechnologien keine optionalen Extras, sondern systemische Voraussetzungen.","Erneuerbare Energien brauchen Speicher, weil Angebot und Nachfrage oft nicht übereinstimmen.","Das Netz braucht Umbau, weil Wind und Sonne nicht auf Abruf liefern können.","Ohne Speicher und Netzausbau ist 100% erneuerbare Energie nicht möglich."],"correctAnswer":"Die Energiewende steht vor einem systemtechnischen Grundproblem: Erneuerbarer Strom ist inhärent volatil — Wind weht nicht immer, Sonne scheint nicht immer — und das Netz muss in Echtzeit Angebot und Nachfrage ausgleichen. Auf dem Weg zu einem System mit 80% erneuerbarer Stromerzeugung sind massiver Netzausbau, Lastflexibilisierung und skalierbare Speichertechnologien keine optionalen Extras, sondern systemische Voraussetzungen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Quantencomputing ist eine strategische Wette auf eine Technologie, die in 10 Jahren transformativ sein ___.","options":["könnte","würde","wird","sollte"],"correctAnswer":"könnte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The promotion of SMEs was a strategic bet on decentralised innovation","wordBankItems":["Die","Förderung","des","Mittelstands","war","eine","strategische","Wette","auf","dezentrale","Innovation","."],"correctAnswer":"Die Förderung des Mittelstands war eine strategische Wette auf dezentrale Innovation ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Wettbewerbsfähig'' means?","options":["competitive","viable","profitable","marketable"],"correctAnswer":"competitive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002fd',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss climate change and climate policy at B2","Use Klimawandel und Klimapolitik vocabulary","Talk about Germany''s climate targets, Paris Agreement, and climate justice"],"explanation":{"intro":"Climate change and climate policy vocabulary covers the Paris Agreement, Germany''s climate targets, and climate justice at B2.","culturalNote":"Klimawandel und Klimapolitik: Germany: Klimaschutzgesetz (2019 — amended 2023 — sectoral targets — 65% reduction by 2030, climate neutral 2045). Key: Bundesverfassungsgericht ruling April 2021 — Klimaschutz als Grundrecht: previous climate law violated intergenerational equity (Gen. Neubauer et al. vs. Germany). IPCC (Intergovernmental Panel on Climate Change). Paris Agreement (2015 — 1.5°C/2°C targets — NDCs). Germany: CO2-Preis (EU ETS + national BEHG — Brennstoffemissionshandelsgesetz 2021 — carbon pricing for heating and transport). Klimagerechtigkeit (climate justice — frontline communities bear disproportionate burdens). Klimaflüchtlinge (climate refugees — 20M/year displaced). Fridays for Future (FFF — Greta Thunberg — Germany: 1.4M March 2019). Key concepts: Tipping points (Kipppunkte), carbon budget (Kohlenstoffbudget), net zero (Netto-Null). Loss and damage (Verlust und Schäden — COP27 breakthrough)."},"examples":[{"german":"Das Bundesverfassungsgerichtsurteil von 2021 hat die Klimaschutzpolitik als eine Frage intergenerationaler Gerechtigkeit etabliert: Die Freiheitsrechte zukünftiger Generationen können durch unzureichenden heutigen Klimaschutz verletzt werden — ein Argument, das das Spannungsverhältnis zwischen gegenwärtigen wirtschaftlichen Interessen und den Rechten Noch-Nicht-Geborener in verfassungsrechtlichen Begriffen fasst.","english":"The Federal Constitutional Court ruling of 2021 has established climate protection policy as a question of intergenerational justice: the freedom rights of future generations can be violated by insufficient current climate protection — an argument that frames the tension between present economic interests and the rights of the yet-to-be-born in constitutional terms."},{"german":"Das 1,5-Grad-Ziel des Pariser Abkommens ist ein wissenschaftlich fundierter politischer Grenzwert: Es markiert die Schwelle, jenseits derer die Wahrscheinlichkeit nichtlinearer Kippprozesse — Permafrostauftauen, Meereisschwund, Amazonasdieback — deutlich zunimmt und die Stabilisierungskosten dramatisch steigen. Die Differenz zwischen 1,5°C und 2°C Erwärmung ist keine marginale Abweichung, sondern ein qualitativer Sprung in Risikoniveau und Schadensprofil.","english":"The 1.5-degree target of the Paris Agreement is a scientifically grounded political limit value: it marks the threshold beyond which the probability of non-linear tipping processes — permafrost thaw, sea ice loss, Amazon dieback — increases significantly and stabilisation costs rise dramatically. The difference between 1.5°C and 2°C warming is not a marginal deviation, but a qualitative leap in risk level and damage profile."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the Paris Agreement, Germany''s climate law, and intergenerational justice at B2."}}',
'{"items":[{"word":"intergenerational","translation":"intergenerational","pronunciation":"in-ter-geh-neh-ra-tsyoh-NAHL","example":"Intergenerationale Gerechtigkeit."},{"word":"der Kipppunkt","translation":"tipping point","pronunciation":"dayr KIP-poonkt","example":"Klimatische Kipppunkte."},{"word":"das Kohlenstoffbudget","translation":"carbon budget","pronunciation":"dahs KOH-len-shtof-boo-zhet","example":"Globales Kohlenstoffbudget."},{"word":"nichtlinear","translation":"non-linear","pronunciation":"nikht-li-neh-AR","example":"Nichtlineare Prozesse."},{"word":"jenseits","translation":"beyond","pronunciation":"YEN-zyts","example":"Jenseits der Schwelle."},{"word":"das Schadensprofil","translation":"damage profile","pronunciation":"dahs SHA-dens-pro-feel","example":"Qualitatives Schadensprofil."}]}',
'{"title":"Die Differenz zwischen X und Y ist kein Y sondern ein qualitativer Sprung — the difference is not marginal but a qualitative leap","pattern":"die Differenz zwischen X und Y ist keine marginale Abweichung, sondern ein qualitativer Sprung = the difference between X and Y is not a marginal deviation, but a qualitative leap (keine...Abweichung, sondern...Sprung = not a deviation, but a leap — marks that a quantitative difference entails a qualitative shift in kind, not just degree)","explanation":"Marginale Abweichung = marginal deviation (small quantitative difference). Qualitativer Sprung = qualitative leap (change in kind, not just degree). Die Differenz zwischen 1,5°C und 2°C ist keine marginale Abweichung, sondern ein qualitativer Sprung = The difference between 1.5°C and 2°C is not a marginal deviation, but a qualitative leap. The pattern elevates a seemingly small numerical difference to a qualitatively different category — change in kind, not just scale. Compare: ein Unterschied wie Tag und Nacht (night and day difference — more colloquial), kategorial verschieden (categorically different), ein Schwelleneffekt (a threshold effect), ein Systemwechsel (a system change).","examples":[{"sentence":"Die Differenz zwischen 10% und 20% Armut ist keine marginale Abweichung, sondern ein qualitativer Sprung in der sozialen Kohäsion.","translation":"The difference between 10% and 20% poverty is not a marginal deviation, but a qualitative leap in social cohesion."},{"sentence":"Zwischen Reform und Revolution liegt kein gradueller Unterschied, sondern ein qualitativer Sprung.","translation":"Between reform and revolution lies not a gradual difference, but a qualitative leap."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Kipppunkt'' means?","options":["tipping point","threshold point","turning point","critical point"],"correctAnswer":"tipping point"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Federal Constitutional Court ruling of 2021 has established climate protection policy as a question of intergenerational justice: the freedom rights of future generations can be violated by insufficient current climate protection — an argument that frames the tension between present economic interests and the rights of the yet-to-be-born in constitutional terms.","options":["Das Bundesverfassungsgerichtsurteil von 2021 hat die Klimaschutzpolitik als eine Frage intergenerationaler Gerechtigkeit etabliert: Die Freiheitsrechte zukünftiger Generationen können durch unzureichenden heutigen Klimaschutz verletzt werden — ein Argument, das das Spannungsverhältnis zwischen gegenwärtigen wirtschaftlichen Interessen und den Rechten Noch-Nicht-Geborener in verfassungsrechtlichen Begriffen fasst.","Das BVerfG stärkte den Klimaschutz durch Anerkennung zukünftiger Freiheitsrechte.","Klimaschutz ist eine Grundrechtsfrage: unzureichende Maßnahmen verletzen Rechte zukünftiger Menschen.","Das Klimaurteil 2021 verknüpfte Klimaschutz mit intergenerationaler Gerechtigkeit."],"correctAnswer":"Das Bundesverfassungsgerichtsurteil von 2021 hat die Klimaschutzpolitik als eine Frage intergenerationaler Gerechtigkeit etabliert: Die Freiheitsrechte zukünftiger Generationen können durch unzureichenden heutigen Klimaschutz verletzt werden — ein Argument, das das Spannungsverhältnis zwischen gegenwärtigen wirtschaftlichen Interessen und den Rechten Noch-Nicht-Geborener in verfassungsrechtlichen Begriffen fasst."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Zwischen Reform und Revolution liegt kein gradueller Unterschied, sondern ein qualitativer ___.","options":["Sprung","Unterschied","Wandel","Wechsel"],"correctAnswer":"Sprung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Between reform and revolution lies not a gradual difference but a qualitative leap","wordBankItems":["Zwischen","Reform","und","Revolution","liegt","kein","gradueller","Unterschied",",","sondern","ein","qualitativer","Sprung","."],"correctAnswer":"Zwischen Reform und Revolution liegt kein gradueller Unterschied , sondern ein qualitativer Sprung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Jenseits'' means?","options":["beyond","across","past","over"],"correctAnswer":"beyond"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002fe',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss biodiversity and nature conservation at B2","Use Biodiversität und Naturschutz vocabulary","Talk about species extinction, Germany''s nature reserves, and the biodiversity crisis"],"explanation":{"intro":"Biodiversity and nature conservation vocabulary covers the sixth mass extinction, Germany''s biodiversity crisis, and nature conservation at B2.","culturalNote":"Biodiversität und Naturschutz: Germany: Insektensterben (insect decline — Germany: 75% decline in flying insects in 27 years — 2017 Krefeld study — Neonikotinoide). Artensterben (species extinction — 6th mass extinction — IPBES 2019: 1 million species at risk). Bundesnaturschutzgesetz (Federal Nature Conservation Act). Schutzgebiete (protected areas — Natura 2000 — 15% German land area). Nationalparks (Germany: 16 — Black Forest, Bavarian Forest, Harz, Berchtesgaden, Wattenmeer — total 0.6% land area). Moorschutz (peat bog protection — CO2 sinks). Auenrenaturierung (floodplain restoration). Biodiversitätsstrategie (Germany 2030 — 30×30 target). Key debate: Neonikotinoids (pesticides — banned EU 2018 for outdoor use). Lichtverschmutzung (light pollution — insects). Wolf (return of the wolf — Wolfsrudel — farmer conflicts — Abschussquoten debate). Artenschutz vs. Landwirtschaft."},"examples":[{"german":"Die Biodiversitätskrise ist die stille Parallelkrise zur Klimakrise: Während Klimawandel durch Temperaturrekorde und Extremwetterereignisse mediale Aufmerksamkeit erzeugt, vollzieht sich der Artenrückgang schrittweise und schwer messbar — aber nicht weniger bedrohlich. Der Verlust von Bestäubern und Bodenorganismen hat direkte Konsequenzen für die Nahrungsmittelproduktion, die über die ökologischen Kaskadeneffekte hinausgehen.","english":"The biodiversity crisis is the silent parallel crisis to the climate crisis: while climate change generates media attention through temperature records and extreme weather events, the species decline proceeds gradually and is difficult to measure — but no less threatening. The loss of pollinators and soil organisms has direct consequences for food production that go beyond the ecological cascade effects."},{"german":"Das Konzept der ökologischen Kassadeneffekte erklärt, warum Biodiversitätsverlust nicht linear verläuft: Wenn eine Schlüsselart aus einem Ökosystem verschwindet, verändert das Nahrungsnetze und ermöglicht das Verschwinden weiterer abhängiger Arten — ein sich verstärkender Prozess, der Ökosysteme in neue, oft degradiertere Gleichgewichtszustände treibt.","english":"The concept of ecological cascade effects explains why biodiversity loss does not proceed linearly: when a keystone species disappears from an ecosystem, it alters food webs and enables the disappearance of further dependent species — a self-reinforcing process that drives ecosystems towards new, often more degraded equilibrium states."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the biodiversity crisis, insect decline, and ecological cascade effects at B2."}}',
'{"items":[{"word":"der Artenrückgang","translation":"species decline","pronunciation":"dayr AR-ten-rük-gank","example":"Massiver Artenrückgang."},{"word":"der Bestäuber","translation":"pollinator","pronunciation":"dayr beh-SHTOY-ber","example":"Verlust von Bestäubern."},{"word":"die Kaskade","translation":"cascade","pronunciation":"dee kas-KAH-deh","example":"Ökologische Kaskadeneffekte."},{"word":"schrittweise","translation":"gradually","pronunciation":"SHRIT-vy-zeh","example":"Schrittweise verschlechtern."},{"word":"die Schlüsselart","translation":"keystone species","pronunciation":"dee SHLÜ-sel-art","example":"Schlüsselart verschwindet."},{"word":"der Gleichgewichtszustand","translation":"equilibrium state","pronunciation":"dayr GLYKH-geh-vikhts-tsoo-shtant","example":"Neuer Gleichgewichtszustand."}]}',
'{"title":"X vollzieht sich schrittweise und schwer messbar — X proceeds gradually and is difficult to measure","pattern":"X vollzieht sich schrittweise und schwer messbar = X proceeds gradually and is difficult to measure (sich vollziehen = to take place, proceed — reflexive; schrittweise = gradually; schwer messbar = difficult to measure)","explanation":"Sich vollziehen = to take place, proceed, unfold (vollziehen = to complete, carry out; reflexive sich vollziehen = to unfold on its own, without a clear agent). Schrittweise = step by step, gradually. Schwer messbar = difficult to measure (schwer = difficult + messbar = measurable). The pattern describes slow, cumulative processes that are hard to perceive and quantify — contrast to sudden, visible events. Der Artenrückgang vollzieht sich schrittweise und schwer messbar = species decline proceeds gradually and is difficult to measure. Compare: schleichend (creeping, insidious — more negative), unmerklich (imperceptibly — emphasises absence of perception), langsam und kaum wahrnehmbar (slowly and barely perceptible — more descriptive).","examples":[{"sentence":"Der Kulturwandel vollzieht sich schrittweise und ist schwer messbar.","translation":"Cultural change proceeds gradually and is difficult to measure."},{"sentence":"Bodendegradation vollzieht sich schrittweise, bis sie irreversibel ist.","translation":"Soil degradation proceeds gradually until it is irreversible."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Artenrückgang'' means?","options":["species decline","species loss","biodiversity loss","extinction"],"correctAnswer":"species decline"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The biodiversity crisis is the silent parallel crisis to the climate crisis: while climate change generates media attention through temperature records and extreme weather events, the species decline proceeds gradually and is difficult to measure — but no less threatening. The loss of pollinators and soil organisms has direct consequences for food production that go beyond the ecological cascade effects.","options":["Die Biodiversitätskrise ist die stille Parallelkrise zur Klimakrise: Während Klimawandel durch Temperaturrekorde und Extremwetterereignisse mediale Aufmerksamkeit erzeugt, vollzieht sich der Artenrückgang schrittweise und schwer messbar — aber nicht weniger bedrohlich. Der Verlust von Bestäubern und Bodenorganismen hat direkte Konsequenzen für die Nahrungsmittelproduktion, die über die ökologischen Kaskadeneffekte hinausgehen.","Das Insektensterben hat direkte Folgen für die Ernte, weil Bestäuber fehlen.","Biodiversitätsverlust ist genauso bedrohlich wie der Klimawandel — nur weniger sichtbar.","Artenrückgang vollzieht sich still und langsam, aber seine Folgen sind drastisch."],"correctAnswer":"Die Biodiversitätskrise ist die stille Parallelkrise zur Klimakrise: Während Klimawandel durch Temperaturrekorde und Extremwetterereignisse mediale Aufmerksamkeit erzeugt, vollzieht sich der Artenrückgang schrittweise und schwer messbar — aber nicht weniger bedrohlich. Der Verlust von Bestäubern und Bodenorganismen hat direkte Konsequenzen für die Nahrungsmittelproduktion, die über die ökologischen Kaskadeneffekte hinausgehen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Kulturwandel vollzieht sich schrittweise und ist schwer ___.","options":["messbar","erkennbar","sichtbar","feststellbar"],"correctAnswer":"messbar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Soil degradation proceeds gradually until it is irreversible","wordBankItems":["Bodendegradation","vollzieht","sich","schrittweise",",","bis","sie","irreversibel","ist","."],"correctAnswer":"Bodendegradation vollzieht sich schrittweise , bis sie irreversibel ist ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Schrittweise'' means?","options":["gradually","step by step","incrementally","progressively"],"correctAnswer":"gradually"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ff',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss water and resource scarcity at B2","Use Wasser und Ressourcenknappheit vocabulary","Talk about global water scarcity, Germany''s water management, and virtual water trade"],"explanation":{"intro":"Water and resource scarcity vocabulary covers global water crisis, virtual water trade, and Germany''s water management at B2.","culturalNote":"Wasser und Ressourcenknappheit: Global: 2.2 billion without safe drinking water (WHO/UNICEF 2019). Germany: wasserreiches Land (water-rich — 180L/day per capita — one of highest). Wasserkrise (water crisis — global — 40% of world population in water-scarce regions). Virtuelles Wasser (virtual water — embedded water in products — 1kg beef = 15,400L; 1kg cotton = 10,000L). Wasserkreislauf (water cycle). Grundwasser (groundwater — Grundwasserspiegel — sinking levels in Eastern Germany). Wasserversorgung (water supply — Germany: municipal, Stadtwerke). Wasserreinigung (water treatment). Wasserverschmutzung (water pollution — nitrate — Düngeverordnung controversy — Germany in EU court). Climate change and water: Dürre (drought — 2018, 2019, 2020 — Germany), Überschwemmungen (floods — Ahrtal 2021 — 135 dead). Water governance: Transboundary rivers (Rhein, Donau, Elbe — international management). Water as human right (UN 2010)."},"examples":[{"german":"Die globale Wasserkrise ist eine Frage ungleicher Verteilung, nicht absoluter Knappheit: Die Erde verfügt über ausreichend Süßwasser — aber 97,5% des gesamten Wasservorkommens ist Salzwasser, nur 0,5% direkt nutzbar; zudem ist das verfügbare Süßwasser ungleich verteilt, während der Wasserverbrauch durch Bevölkerungswachstum, Landwirtschaft und Industrialisierung steigt und Klimawandel die Verfügbarkeit räumlich und zeitlich neu verteilt.","english":"The global water crisis is a question of unequal distribution, not absolute scarcity: the earth has sufficient fresh water — but 97.5% of the total water supply is salt water, only 0.5% directly usable; moreover, the available fresh water is unequally distributed, while water consumption rises through population growth, agriculture, and industrialisation, and climate change redistributes availability spatially and temporally."},{"german":"Das Konzept des virtuellen Wassers offenbart die verborgene Wasserdimension des globalen Handels: Wenn wasserarme Länder Getreide importieren statt es selbst anzubauen, importieren sie de facto das Wasser, das für die Produktion benötigt worden wäre — ein impliziter Wasserimport, der Wasserknappheit lindern kann, aber auch Wasserabhängigkeiten schafft.","english":"The concept of virtual water reveals the hidden water dimension of global trade: when water-poor countries import grain instead of growing it themselves, they are in effect importing the water that would have been needed for production — an implicit water import that can alleviate water scarcity, but also creates water dependencies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss virtual water, global water distribution, and climate change impacts on water at B2."}}',
'{"items":[{"word":"die Knappheit","translation":"scarcity","pronunciation":"dee KNAP-hyt","example":"Ressourcenknappheit."},{"word":"die Verteilung","translation":"distribution","pronunciation":"dee fer-TY-loong","example":"Ungleiche Verteilung."},{"word":"das Süßwasser","translation":"fresh water","pronunciation":"dahs ZÜS-vas-er","example":"Süßwasservorkommen."},{"word":"de facto","translation":"in effect/in fact","pronunciation":"deh FAK-toh","example":"De facto importieren."},{"word":"lindern","translation":"to alleviate","pronunciation":"LIN-dern","example":"Wasserknappheit lindern."},{"word":"offenbaren","translation":"to reveal","pronunciation":"OF-en-bah-ren","example":"Die verborgene Dimension offenbaren."}]}',
'{"title":"X offenbart die verborgene Y-Dimension von Z — X reveals the hidden Y dimension of Z","pattern":"X offenbart die verborgene Y-Dimension von Z = X reveals the hidden Y-dimension of Z (offenbaren = to reveal, unveil; verborgen = hidden, concealed; X (concept/analysis) shows that Z has a Y-dimension that is not normally visible)","explanation":"Offenbaren = to reveal, make manifest (offenbar = obvious/apparent — offenbaren = to make apparent, reveal). Verborgen = hidden (concealed from normal view). Die verborgene Y-Dimension = the hidden Y dimension (dimension that is there but not normally perceived). Das Konzept des virtuellen Wassers offenbart die verborgene Wasserdimension des Handels = the concept of virtual water reveals the hidden water dimension of trade. The pattern is used when an analytical concept (virtual water, carbon footprint, labour value) makes visible a dimension of something that is normally invisible (water content, CO2, labour). Compare: aufzeigen (to show — more neutral), sichtbar machen (to make visible — more visual/direct), zum Vorschein bringen (to bring to light — more discovery-focused), enthüllen (to unveil — stronger, more dramatic).","examples":[{"sentence":"Die Analyse offenbart die verborgene soziale Dimension des Klimawandels.","translation":"The analysis reveals the hidden social dimension of climate change."},{"sentence":"Das Konzept offenbart die verborgene Machtdimension scheinbar neutraler Regeln.","translation":"The concept reveals the hidden power dimension of apparently neutral rules."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Lindern'' means?","options":["to alleviate","to reduce","to ease","to mitigate"],"correctAnswer":"to alleviate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The concept of virtual water reveals the hidden water dimension of global trade: when water-poor countries import grain instead of growing it themselves, they are in effect importing the water that would have been needed for production — an implicit water import that can alleviate water scarcity, but also creates water dependencies.","options":["Das Konzept des virtuellen Wassers offenbart die verborgene Wasserdimension des globalen Handels: Wenn wasserarme Länder Getreide importieren statt es selbst anzubauen, importieren sie de facto das Wasser, das für die Produktion benötigt worden wäre — ein impliziter Wasserimport, der Wasserknappheit lindern kann, aber auch Wasserabhängigkeiten schafft.","Virtuelles Wasser steckt in allem, was wir importieren — Nahrung, Kleidung, Energie.","Wasserarme Länder können Wasserknappheit umgehen, indem sie wasserintensive Güter importieren.","Jeder Importartikel enthält verstecktes Wasser, das im Exportland verbraucht wurde."],"correctAnswer":"Das Konzept des virtuellen Wassers offenbart die verborgene Wasserdimension des globalen Handels: Wenn wasserarme Länder Getreide importieren statt es selbst anzubauen, importieren sie de facto das Wasser, das für die Produktion benötigt worden wäre — ein impliziter Wasserimport, der Wasserknappheit lindern kann, aber auch Wasserabhängigkeiten schafft."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Analyse offenbart die verborgene soziale Dimension des ___.","options":["Klimawandels","Problems","Themas","Wandels"],"correctAnswer":"Klimawandels"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The concept reveals the hidden power dimension of apparently neutral rules","wordBankItems":["Das","Konzept","offenbart","die","verborgene","Machtdimension","scheinbar","neutraler","Regeln","."],"correctAnswer":"Das Konzept offenbart die verborgene Machtdimension scheinbar neutraler Regeln ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Knappheit'' means?","options":["scarcity","shortage","deficit","insufficiency"],"correctAnswer":"scarcity"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000300',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss circular economy at B2","Use Kreislaufwirtschaft vocabulary","Talk about circular economy principles, Germany''s recycling system, and the linear vs. circular model"],"explanation":{"intro":"Circular economy vocabulary covers Germany''s recycling achievements, circular economy principles, and the linear vs. circular economy debate at B2.","culturalNote":"Kreislaufwirtschaft: Germany: Recyclingweltmeister (recycling world champion — ~66% recycling rate — highest globally). Key: Green Dot System (Grüner Punkt — Dual System — Verpackungsrecycling). DSD (Duales System Deutschland — 1991). KrWG (Kreislaufwirtschaftsgesetz — Circular Economy Act). Pfandsystem (deposit system — Einwegpfand — Mehrwegpfand — bottles, cans). Key: EU Circular Economy Action Plan (2020 — Ecodesign, repair, right to repair). Geplante Obsoleszenz (planned obsolescence — iPhone battery controversy). Key concept: Cradle to Cradle (William McDonough/Michael Braungart — German-American collaboration — all materials as nutrients — technical or biological cycle). Ellen MacArthur Foundation (key CE think tank). Urban mining. Produktlebensdauer (product longevity). Reparierbarkeit (repairability — right to repair legislation EU 2024). Key tension: business models built on linear vs. circular economy transformation."},"examples":[{"german":"Die Kreislaufwirtschaft stellt das Linearmodell grundlegend in Frage: Statt des ressourcenintensiven ''Take-Make-Dispose''-Zyklus soll eine zirkuläre Wirtschaft Materialien in geschlossenen Kreisläufen zirkulieren lassen — als technische Nährstoffe in Produktsystemen oder als biologische Nährstoffe in ökologischen Systemen. Der Übergang erfordert nicht nur Recycling, sondern eine Neugestaltung von Produkten, Geschäftsmodellen und Produktionssystemen von Anfang an.","english":"The circular economy fundamentally questions the linear model: instead of the resource-intensive ''take-make-dispose'' cycle, a circular economy should circulate materials in closed loops — as technical nutrients in product systems or as biological nutrients in ecological systems. The transition requires not only recycling, but a redesign of products, business models, and production systems from the outset."},{"german":"Deutschlands Stellung als Recyclingweltmeister verdeckt eine wichtige konzeptionelle Unterscheidung: Recycling ist nur eine Kreislaufstrategie auf einem Kontinuum — am effektivsten sind Strategien, die Abfall ganz vermeiden (Cradle-to-Cradle-Design, Reparatur, Wiederverwendung) und erst wenn alles andere scheitert, recyceln. Eine Fokussierung auf Recyclingraten kann die überlegenen Strategien der Abfallvermeidung und Lebensdauerverlängerung verdecken.","english":"Germany''s position as recycling world champion conceals an important conceptual distinction: recycling is only one circular strategy on a continuum — most effective are strategies that avoid waste entirely (cradle-to-cradle design, repair, reuse) and recycle only when everything else fails. A focus on recycling rates can conceal the superior strategies of waste avoidance and lifetime extension."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss circular economy principles, Cradle-to-Cradle, and Germany''s recycling system at B2."}}',
'{"items":[{"word":"das Linearmodell","translation":"linear model","pronunciation":"dahs li-neh-AR-mo-del","example":"Das Linearmodell überwinden."},{"word":"der Nährstoff","translation":"nutrient","pronunciation":"dayr NÄR-shtof","example":"Technische Nährstoffe."},{"word":"zirkulieren","translation":"to circulate","pronunciation":"tsir-koo-LEE-ren","example":"Materialien zirkulieren lassen."},{"word":"die Abfallvermeidung","translation":"waste avoidance","pronunciation":"dee AB-fal-fer-my-doong","example":"Abfallvermeidung priorisieren."},{"word":"verdecken","translation":"to conceal","pronunciation":"fer-DEK-en","example":"Wichtige Unterschiede verdecken."},{"word":"das Kontinuum","translation":"continuum","pronunciation":"dahs kon-TI-noo-oom","example":"Auf einem Kontinuum."}]}',
'{"title":"X stellt Y grundlegend in Frage — X fundamentally questions Y","pattern":"X stellt Y grundlegend in Frage = X fundamentally questions Y (in Frage stellen = to call into question — separable: stellt...in Frage; grundlegend = fundamentally — marks a radical, not partial questioning)","explanation":"In Frage stellen = to call into question (stellen...in Frage — separable — brings into the space of doubt). Grundlegend = fundamentally, at the roots (grundlegend = grundlegend: Grund = ground/foundation + legend = laying — foundational). Die Kreislaufwirtschaft stellt das Linearmodell grundlegend in Frage = the circular economy fundamentally questions the linear model. The pattern marks a deep challenge to an existing model or assumption — not just tweaking but questioning at the foundations. Compare: bezweifeln (to doubt — weaker, internal), ablehnen (to reject — more decisive), herausfordern (to challenge — active contest without necessarily questioning the foundations), überholen (to make obsolete — gentler, by time/development).","examples":[{"sentence":"Diese Forschung stellt die bisherige Theorie grundlegend in Frage.","translation":"This research fundamentally questions the existing theory."},{"sentence":"Der Skandal stellt das Vertrauen in die Institution grundlegend in Frage.","translation":"The scandal fundamentally questions trust in the institution."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Zirkulieren'' means?","options":["to circulate","to cycle","to flow","to rotate"],"correctAnswer":"to circulate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s position as recycling world champion conceals an important conceptual distinction: recycling is only one circular strategy on a continuum — most effective are strategies that avoid waste entirely (cradle-to-cradle design, repair, reuse) and recycle only when everything else fails. A focus on recycling rates can conceal the superior strategies of waste avoidance and lifetime extension.","options":["Deutschlands Stellung als Recyclingweltmeister verdeckt eine wichtige konzeptionelle Unterscheidung: Recycling ist nur eine Kreislaufstrategie auf einem Kontinuum — am effektivsten sind Strategien, die Abfall ganz vermeiden (Cradle-to-Cradle-Design, Reparatur, Wiederverwendung) und erst wenn alles andere scheitert, recyceln. Eine Fokussierung auf Recyclingraten kann die überlegenen Strategien der Abfallvermeidung und Lebensdauerverlängerung verdecken.","Recycling allein reicht nicht — Reparatur und Wiederverwendung sind besser.","Deutschland ist gut im Recycling, aber Abfallvermeidung wird vernachlässigt.","Die beste Kreislaufwirtschaft produziert gar keinen Abfall — Recycling ist die zweitbeste Option."],"correctAnswer":"Deutschlands Stellung als Recyclingweltmeister verdeckt eine wichtige konzeptionelle Unterscheidung: Recycling ist nur eine Kreislaufstrategie auf einem Kontinuum — am effektivsten sind Strategien, die Abfall ganz vermeiden (Cradle-to-Cradle-Design, Reparatur, Wiederverwendung) und erst wenn alles andere scheitert, recyceln. Eine Fokussierung auf Recyclingraten kann die überlegenen Strategien der Abfallvermeidung und Lebensdauerverlängerung verdecken."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Forschung stellt die bisherige Theorie grundlegend in ___.","options":["Frage","Zweifel","Frage stelle","Kritik"],"correctAnswer":"Frage"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The scandal fundamentally questions trust in the institution","wordBankItems":["Der","Skandal","stellt","das","Vertrauen","in","die","Institution","grundlegend","in","Frage","."],"correctAnswer":"Der Skandal stellt das Vertrauen in die Institution grundlegend in Frage ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verdecken'' means?","options":["to conceal","to cover","to hide","to mask"],"correctAnswer":"to conceal"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000301',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss environmental justice at B2","Use Umweltgerechtigkeit vocabulary","Talk about environmental racism, unequal pollution burdens, and Germany''s environmental justice"],"explanation":{"intro":"Environmental justice vocabulary covers environmental racism, unequal pollution burdens, and Germany''s environmental justice debates at B2.","culturalNote":"Umweltgerechtigkeit: Key origin: Environmental justice movement — USA — 1982 Warren County — PCB landfill in Black community — Civil Rights and environment linked. Key: Environmental racism (Umweltrassismus — communities of colour disproportionately bear environmental burdens — toxic waste, polluting industries). Germany: less data on environmental racism — but Lärm (noise pollution — Flughafen Frankfurt — airport expansion), Luftverschmutzung (air pollution — Dieselskandal — Fahrverbote), contaminated soils — correlate with lower-income areas. Klimagerechtigkeit (climate justice — Global South bears costs of Global North emissions). IPCC: Global South most vulnerable. Loss and damage (COP27). Just Transition (just transition — coal regions Lausitz, Rheinisches Revier — social cushioning for structural change). Umweltverbände (environmental organisations — BUND, NABU, Greenpeace, FoE). Environmental rights in Grundgesetz: Art. 20a — staatliche Pflicht zum Umweltschutz (state duty of environmental protection)."},"examples":[{"german":"Umweltgerechtigkeit erweitert den ökologischen Diskurs um eine Verteilungsdimension: Ökologische Belastungen — Lärm, Schadstoffemissionen, Hitzeinseleffekte — sind sozialräumlich ungleich verteilt und korrelieren mit sozioökonomischen Benachteiligungen. Umweltpolitik, die diese Ungleichverteilung ignoriert, reproduziert Ungleichheiten, statt sie zu korrigieren — und ist deshalb nicht nur ökologisch, sondern auch sozialpolitisch zu bewerten.","english":"Environmental justice expands the ecological discourse with a distributional dimension: ecological burdens — noise, pollutant emissions, heat island effects — are unequally distributed sociospatially and correlate with socioeconomic disadvantages. Environmental policy that ignores this unequal distribution reproduces inequalities instead of correcting them — and must therefore be assessed not only ecologically, but also sociopolitically."},{"german":"Die gerechte Transformation der Kohlerevier illustriert das Spannungsverhältnis zwischen ökologischem Notwendigkeit und sozialer Verantwortung: Ein Kohleausstieg, der Zehntausende von Arbeitsplätzen vernichtet, ohne tragfähige wirtschaftliche Alternativen zu schaffen, belastet besonders Regionen, die bereits von Deindustrialisierung getroffen wurden — eine Ungerechtigkeit, die Klimaschutz delegitimiert, wenn seine Kosten ungleich verteilt sind.","english":"The just transformation of the coal regions illustrates the tension between ecological necessity and social responsibility: a coal phase-out that destroys tens of thousands of jobs without creating viable economic alternatives particularly burdens regions already hit by deindustrialisation — an injustice that delegitimises climate protection when its costs are unequally distributed."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss environmental justice, just transition, and unequal pollution burdens at B2."}}',
'{"items":[{"word":"die Belastung","translation":"burden/pollution load","pronunciation":"dee beh-LAS-toong","example":"Ökologische Belastungen."},{"word":"sozialräumlich","translation":"socio-spatially","pronunciation":"zo-TSYAHL-roym-likh","example":"Sozialräumlich verteilt."},{"word":"die Benachteiligung","translation":"disadvantage","pronunciation":"dee beh-NAKH-ty-li-goong","example":"Sozioökonomische Benachteiligung."},{"word":"reproduzieren","translation":"to reproduce","pronunciation":"reh-pro-doo-ZEE-ren","example":"Ungleichheiten reproduzieren."},{"word":"delegitimieren","translation":"to delegitimise","pronunciation":"deh-leh-gi-ti-MEE-ren","example":"Klimaschutz delegitimieren."},{"word":"tragfähig","translation":"viable","pronunciation":"TRAK-fä-ikh","example":"Tragfähige Alternativen."}]}',
'{"title":"X erweitert Y um eine Z-Dimension — X expands Y with a Z dimension","pattern":"X erweitert Y um eine Z-Dimension = X expands Y with a Z dimension (erweitern um = to expand by; Dimension = dimension — marks that X adds a new analytical layer/perspective to Y that was previously absent)","explanation":"Erweitern um = to expand by/with (erweitern = to expand; um + accusative = by X). Eine Dimension = a dimension (a new analytical plane or perspective). Umweltgerechtigkeit erweitert den ökologischen Diskurs um eine Verteilungsdimension = environmental justice expands the ecological discourse with a distributional dimension. The pattern marks analytical enrichment: an existing framework (Y = ecological discourse) gets a new dimension (Z = distributional) added by X (environmental justice). Compare: bereichern um (to enrich with — more positive/cultural), hinzufügen (to add — more additive/mechanical), ergänzen durch (to supplement with — more neutral), eröffnen (to open up — more spatial/potential).","examples":[{"sentence":"Die intersektionale Perspektive erweitert den Feminismus um eine Klassendimension.","translation":"The intersectional perspective expands feminism with a class dimension."},{"sentence":"Sozialpsychologie erweitert die Ökonomie um eine Verhaltensdimension.","translation":"Social psychology expands economics with a behavioural dimension."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Tragfähig'' means?","options":["viable","sustainable","workable","feasible"],"correctAnswer":"viable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Environmental justice expands the ecological discourse with a distributional dimension: ecological burdens — noise, pollutant emissions, heat island effects — are unequally distributed sociospatially and correlate with socioeconomic disadvantages. Environmental policy that ignores this unequal distribution reproduces inequalities instead of correcting them — and must therefore be assessed not only ecologically, but also sociopolitically.","options":["Umweltgerechtigkeit erweitert den ökologischen Diskurs um eine Verteilungsdimension: Ökologische Belastungen — Lärm, Schadstoffemissionen, Hitzeinseleffekte — sind sozialräumlich ungleich verteilt und korrelieren mit sozioökonomischen Benachteiligungen. Umweltpolitik, die diese Ungleichverteilung ignoriert, reproduziert Ungleichheiten, statt sie zu korrigieren — und ist deshalb nicht nur ökologisch, sondern auch sozialpolitisch zu bewerten.","Umweltverschmutzung trifft einkommensschwache Bevölkerungen am stärksten.","Umweltgerechtigkeit verbindet Ökologie mit sozialer Ungleichheit.","Schadstoffe sind nicht gleichmäßig verteilt — ärmere Gebiete leiden mehr."],"correctAnswer":"Umweltgerechtigkeit erweitert den ökologischen Diskurs um eine Verteilungsdimension: Ökologische Belastungen — Lärm, Schadstoffemissionen, Hitzeinseleffekte — sind sozialräumlich ungleich verteilt und korrelieren mit sozioökonomischen Benachteiligungen. Umweltpolitik, die diese Ungleichverteilung ignoriert, reproduziert Ungleichheiten, statt sie zu korrigieren — und ist deshalb nicht nur ökologisch, sondern auch sozialpolitisch zu bewerten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die intersektionale Perspektive erweitert den Feminismus um eine ___.","options":["Klassendimension","Dimension","Perspektive","Sichtweise"],"correctAnswer":"Klassendimension"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Social psychology expands economics with a behavioural dimension","wordBankItems":["Sozialpsychologie","erweitert","die","Ökonomie","um","eine","Verhaltensdimension","."],"correctAnswer":"Sozialpsychologie erweitert die Ökonomie um eine Verhaltensdimension ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Delegitimieren'' means?","options":["to delegitimise","to undermine","to discredit","to erode"],"correctAnswer":"to delegitimise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000302',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss international climate negotiations at B2","Use Internationale Klimaverhandlungen vocabulary","Talk about COP, IPCC, Paris Agreement implementation, and climate diplomacy"],"explanation":{"intro":"International climate negotiations vocabulary covers COP, NDCs, climate finance, and the geopolitics of climate diplomacy at B2.","culturalNote":"Internationale Klimaverhandlungen: Key: UNFCCC (UN Framework Convention on Climate Change — 1992 Rio). COP (Conference of the Parties — annual — COP21 Paris 2015, COP26 Glasgow 2021, COP27 Sharm el-Sheikh 2022 — Loss and Damage Fund breakthrough, COP28 Dubai 2023 — fossil fuel phase-out language). NDC (Nationally Determined Contribution — each country''s climate pledge). Key: Gap between NDC pledges and 1.5°C trajectory (UNEP Gap Report). Klimafinanzierung (climate finance — 100bn/year pledged by developed nations to developing nations by 2020 — target missed). Green Climate Fund. Key: CBDR (Common But Differentiated Responsibilities — developed nations bear more responsibility). Loss and damage (compensation for unavoidable climate impacts — breakthrough COP27). Key figures: Xie Zhenhua (China), John Kerry (USA). Germany: EU leadership. OECD vs. developing countries. Small island states (AOSIS — existential threat). Klimaflucht (climate migration — 200M by 2050 estimates)."},"examples":[{"german":"Die Pariser Klimaverhandlungen haben einen strukturellen Innovationssprung vollzogen: Statt verbindlicher von oben festgelegter Ziele setzt das Abkommen auf ein System nationaler Selbstverpflichtungen — NDCs — die alle fünf Jahre nachgeschärft werden sollen. Dieser ''ratchet mechanism'' löst das Souveränitätsproblem früherer Abkommen, schafft aber ein Umsetzungsproblem: Die Summe der NDCs reicht derzeit nicht aus, um die 1,5-Grad-Grenze einzuhalten.","english":"The Paris climate negotiations achieved a structural innovation leap: instead of binding top-down targets, the agreement relies on a system of national self-commitments — NDCs — that are to be tightened every five years. This ''ratchet mechanism'' solves the sovereignty problem of earlier agreements, but creates an implementation problem: the sum of the NDCs is currently insufficient to stay within the 1.5-degree limit."},{"german":"Das Prinzip der ''gemeinsamen, aber differenzierten Verantwortung'' ist der ethische Kern internationaler Klimaverhandlungen: Historische Emissionen stammen überwiegend aus Industrieländern, während die Vulnerabilität gegenüber den Klimaauswirkungen bei einkommensschwachen Ländern des Globalen Südens am höchsten ist — eine Asymmetrie, die Forderungen nach Klimafinanzierung, Technologietransfer und Loss-and-Damage-Kompensationen moralisch begründet.","english":"The principle of ''common but differentiated responsibilities'' is the ethical core of international climate negotiations: historical emissions originate predominantly from industrialised countries, while vulnerability to climate impacts is highest in low-income countries of the Global South — an asymmetry that morally grounds demands for climate finance, technology transfer, and loss-and-damage compensation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the Paris Agreement ratchet mechanism, NDCs, CBDR, and climate finance at B2."}}',
'{"items":[{"word":"die Selbstverpflichtung","translation":"self-commitment","pronunciation":"dee ZELPST-fer-pflikh-toong","example":"Nationale Selbstverpflichtung."},{"word":"nachschärfen","translation":"to tighten (commitments)","pronunciation":"NAKH-sher-fen","example":"NDCs nachschärfen."},{"word":"die Vulnerabilität","translation":"vulnerability","pronunciation":"dee vool-neh-ra-bi-li-TÄT","example":"Klimavulnerabilität."},{"word":"moralisch begründen","translation":"to morally ground/justify","pronunciation":"mo-RAH-lish beh-GRÜN-den","example":"Forderungen moralisch begründen."},{"word":"verbindlich","translation":"binding","pronunciation":"fer-BINT-likh","example":"Verbindliche Ziele."},{"word":"differenziert","translation":"differentiated","pronunciation":"dif-feh-rent-SEERT","example":"Differenzierte Verantwortung."}]}',
'{"title":"X löst Problem Y, schafft aber Problem Z — X solves problem Y but creates problem Z","pattern":"X löst Problem Y, schafft aber (ein neues/das) Problem Z = X solves problem Y, but creates problem Z (lösen = to solve; schaffen = to create — the structure acknowledges that a solution to one problem generates another)","explanation":"Lösen = to solve. Schaffen = to create (not lösen but schaffen — to generate, bring into being). X löst das Souveränitätsproblem, schafft aber ein Umsetzungsproblem = X solves the sovereignty problem, but creates an implementation problem. The pattern is a classic dialectical move in policy analysis: A solution generates a new problem of a different kind. Not a total failure, but an acknowledged trade-off. Compare: kauft sich X auf Kosten von Y (buys X at the cost of Y — more transactional), verlagert das Problem (shifts the problem — problem moves, not solved), tauscht X gegen Y (trades X for Y), creates second-order effects.","examples":[{"sentence":"Automatisierung löst das Kostenproblem, schafft aber ein Beschäftigungsproblem.","translation":"Automation solves the cost problem, but creates an employment problem."},{"sentence":"Zentralisierung löst das Koordinationsproblem, schafft aber ein Demokratieproblem.","translation":"Centralisation solves the coordination problem, but creates a democracy problem."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verbindlich'' means?","options":["binding","obligatory","mandatory","compulsory"],"correctAnswer":"binding"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The principle of ''common but differentiated responsibilities'' is the ethical core of international climate negotiations: historical emissions originate predominantly from industrialised countries, while vulnerability to climate impacts is highest in low-income countries of the Global South — an asymmetry that morally grounds demands for climate finance, technology transfer, and loss-and-damage compensation.","options":["Das Prinzip der ''gemeinsamen, aber differenzierten Verantwortung'' ist der ethische Kern internationaler Klimaverhandlungen: Historische Emissionen stammen überwiegend aus Industrieländern, während die Vulnerabilität gegenüber den Klimaauswirkungen bei einkommensschwachen Ländern des Globalen Südens am höchsten ist — eine Asymmetrie, die Forderungen nach Klimafinanzierung, Technologietransfer und Loss-and-Damage-Kompensationen moralisch begründet.","Der Globale Süden trägt weniger zur Klimakrise bei, leidet aber am meisten darunter.","CBDR bedeutet: Industrieländer müssen mehr für Klimaschutz und -anpassung zahlen.","Klimagerechtigkeit fordert Kompensation von denjenigen, die historisch am meisten emittiert haben."],"correctAnswer":"Das Prinzip der ''gemeinsamen, aber differenzierten Verantwortung'' ist der ethische Kern internationaler Klimaverhandlungen: Historische Emissionen stammen überwiegend aus Industrieländern, während die Vulnerabilität gegenüber den Klimaauswirkungen bei einkommensschwachen Ländern des Globalen Südens am höchsten ist — eine Asymmetrie, die Forderungen nach Klimafinanzierung, Technologietransfer und Loss-and-Damage-Kompensationen moralisch begründet."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Automatisierung löst das Kostenproblem, schafft aber ein ___.","options":["Beschäftigungsproblem","Arbeitsproblem","Jobproblem","Arbeitslosen-Problem"],"correctAnswer":"Beschäftigungsproblem"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Centralisation solves the coordination problem but creates a democracy problem","wordBankItems":["Zentralisierung","löst","das","Koordinationsproblem",",","schafft","aber","ein","Demokratieproblem","."],"correctAnswer":"Zentralisierung löst das Koordinationsproblem , schafft aber ein Demokratieproblem ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Differenziert'' means?","options":["differentiated","nuanced","distinct","varied"],"correctAnswer":"differentiated"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

